{%- doc -%}
  Renders the blog article image block for use within featured blog posts cards.

  @param {object} image - The image object
  @param {string} parent_block_id - The block.id of the parent blog post card
{%- enddoc -%}

{% comment %} Render using unified resource image component {% endcomment %}
{% render 'resource-image',
  content_type: 'articles',
  image_source: image,
  parent_block_id: parent_block_id,
  block_settings: block.settings,
  section_settings: section.settings,
  block_attributes: block.shopify_attributes
%}

{% stylesheet %}
  .featured-blog-posts-card__image {
    width: 100%;
  }

  .featured-blog-posts-card__image .blog-placeholder-svg {
    object-fit: cover;
    width: 100%;
    height: 100%;
  }
{% endstylesheet %}

